PRAGMA user_version=3;
CREATE TABLE "profile_rule_mapping" ("id" TEXT NOT NULL, "profile_id" INTEGER NULL REFERENCES profiles (id) ON DELETE CASCADE, "rule_id" INTEGER NOT NULL REFERENCES rules (id) ON DELETE CASCADE, "scene" TEXT NULL, "order" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "profiles" ("id" INTEGER NOT NULL, "label" TEXT NOT NULL, "current_group_name" TEXT NULL, "url" TEXT NOT NULL, "last_update_date" INTEGER NULL, "overwrite_type" TEXT NOT NULL, "script_id" INTEGER NULL, "auto_update_duration_millis" INTEGER NOT NULL, "subscription_info" TEXT NULL, "auto_update" INTEGER NOT NULL CHECK ("auto_update" IN (0, 1)), "selected_map" TEXT NOT NULL, "unfold_set" TEXT NOT NULL, "order" INTEGER NULL, "match_target" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "rules" ("id" INTEGER NOT NULL, rule_action TEXT NOT NULL DEFAULT "", content TEXT, rule_target TEXT, rule_provider TEXT, sub_rule TEXT, no_resolve INTEGER NOT NULL DEFAULT 0, src INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
